package io.github.diodeme.ji.host.web;

import io.github.diodeme.ji.agent.AgentRuntimeBuilder;
import io.github.diodeme.ji.ai.ModelRef;
import io.github.diodeme.ji.ai.ModelStreamEvent;
import io.github.diodeme.ji.ai.Usage;
import io.github.diodeme.ji.host.LocalTokenService;
import io.github.diodeme.ji.host.PermissionBroker;
import io.github.diodeme.ji.host.PersistentHostStore;
import io.github.diodeme.ji.host.PromptApplicationService;
import io.github.diodeme.ji.host.SessionApplicationService;
import io.github.diodeme.ji.host.sqlite.SqliteHostStorePersistence;
import io.github.diodeme.ji.testkit.ScriptedModelProvider;
import java.io.BufferedReader;
import java.io.DataOutputStream;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.ServerSocket;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.security.SecureRandom;
import java.time.Clock;
import java.util.List;

/** Restartable real Host fixture backed by one temporary SQLite store. */
public final class Stage4RestartHostFixture {
    private Stage4RestartHostFixture() {}

    public static void main(String[] args) throws Exception {
        if (args.length != 2 || !List.of("write", "read").contains(args[0])) {
            throw new IllegalArgumentException("usage: Stage4RestartHostFixture write|read DATABASE");
        }
        var provider = new ScriptedModelProvider();
        if ("write".equals(args[0])) {
            provider.enqueue(List.of(
                    new ScriptedModelProvider.Step.Text("restart-safe reply"),
                    new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
        }
        var permissions = new PermissionBroker(Clock.systemUTC());
        var store = new PersistentHostStore(new SqliteHostStorePersistence(Path.of(args[1])));
        try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionRepository(store)
                .permissionDecider(permissions).build();
             var sessions = new SessionApplicationService(runtime);
             var server = new LocalHostServer(sessions, permissions,
                     new PromptApplicationService(sessions, store), new ModelRef("faux", "faux-1"),
                     new LocalTokenService(new SecureRandom(), Clock.systemUTC()));
             var control = new ServerSocket(0, 1, InetAddress.getLoopbackAddress())) {
            System.out.println("STAGE4_RESTART_HOST_READY http://127.0.0.1:" + server.port()
                    + " CONTROL " + control.getLocalPort());
            System.out.flush();
            try (var connection = control.accept();
                 var commands = new BufferedReader(new InputStreamReader(
                         connection.getInputStream(), StandardCharsets.US_ASCII));
                 var response = new DataOutputStream(connection.getOutputStream())) {
                String command;
                while ((command = commands.readLine()) != null) {
                    if ("STOP".equals(command)) break;
                    if (!"ISSUE_TOKEN".equals(command)) throw new IllegalArgumentException("unexpected command");
                    byte[] token = [REDACTED_CREDENTIAL]
                    response.writeInt(token.length);
                    response.write(token);
                    response.flush();
                    java.util.Arrays.fill(token, (byte) 0);
                }
            }
        }
    }
}
